//
// Handlers for reports.routes.js. Contract: backend/API.md, "reports module
// (Phase 7)". Block N-C.
//
// create_report() decides who may report, and a trigger on reports covers the
// post at its threshold (runbook §1.7). Never count reports or cover a post
// here. The reporter is always req.user.id, never a body field.
//
// ⚠ The answer never reveals the outcome: not how many reports the post has,
// and not whether it was covered. Always 201 { reported: true }.
// ⚠ Never log the details text.
import { supabase } from '../../config/supabase.js';
import { sendError, mapDbError } from '../../utils/respond.js';
import { isUuid } from '../../utils/pagination.js';

// Spec §7 and runbook Appendix A. The reports table checks the same list.
const REASONS = new Set([
  'spam',
  'harassment',
  'hate_speech',
  'sexual_content',
  'child_safety',
  'violence',
  'self_harm',
  'impersonation',
  'misinformation',
  'prohibited_item',
  'other',
]);
const DETAILS_MAX_LENGTH = 500;

/** Only the code and message reach mapDbError, which logs what it can't map:
 *  an error's details can hold the failing row, the reporter's text included. */
const sanitised = (error) => ({ code: error?.code, message: error?.message });

// ───────────────────────────────────────────────────────────────────────────
// POST /api/reports   { target_type, target_id, reason, details? }
// ───────────────────────────────────────────────────────────────────────────
export const createReport = async (req, res) => {
  try {
    const { target_type: targetType, target_id: targetId, reason } = req.body ?? {};
    let details = req.body?.details;

    // Phase 7 reports posts only.
    if (targetType !== 'post') {
      return sendError(res, 400, 'INVALID_FORMAT', { message: 'Only posts can be reported for now.' });
    }
    if (!isUuid(targetId)) return sendError(res, 400, 'INVALID_FORMAT');
    if (!REASONS.has(reason)) return sendError(res, 400, 'INVALID_FORMAT');

    // Optional. Blank counts as none; the limit is in code points, as in the table.
    if (details === undefined || details === null) {
      details = null;
    } else if (typeof details !== 'string') {
      return sendError(res, 400, 'INVALID_FORMAT');
    } else {
      details = details.trim() || null;
      if (details && [...details].length > DETAILS_MAX_LENGTH) return sendError(res, 400, 'INVALID_FORMAT');
    }

    // POST_NOT_FOUND 404, CANNOT_REPORT_OWN 400, a second report → 23505 → DUPLICATE 400.
    const { error } = await supabase.rpc('create_report', {
      p_reporter: req.user.id,
      p_target_type: targetType,
      p_target_id: targetId,
      p_reason: reason,
      p_details: details,
    });
    if (error) return mapDbError(res, sanitised(error));

    return res.status(201).json({ reported: true });
  } catch (error) {
    return mapDbError(res, sanitised(error));
  }
};
